<script setup>
import { onMounted, ref } from 'vue'
import { messageApi } from '../api'
const emit=defineEmits(['close']);const accounts=ref([]),busy=ref(false),error=ref(''),message=ref('');const form=ref({targetUsername:'',subject:'',body:'',linkPath:''})
async function send(){busy.value=true;error.value='';message.value='';try{const result=await messageApi.adminSend({...form.value,targetUsername:form.value.targetUsername||null});message.value=`已投递 ${result.sent} 封消息`;form.value={targetUsername:'',subject:'',body:'',linkPath:''}}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(()=>messageApi.accounts().then(value=>accounts.value=value).catch(e=>error.value=e.message))
</script>
<template><div class="modal-backdrop module-admin-backdrop" @click.self="emit('close')"><form class="upload-modal control-center-modal admin-message-modal" @submit.prevent="send"><button class="modal-close" type="button" @click="emit('close')">×</button><span class="eyebrow">管理员 · 消息投递</span><h2>消息设置</h2><p>可以向全站广播或选择一个账号发送。普通用户之间不能通过这里互相联系。</p><section class="control-center-section"><label>收件人<select v-model="form.targetUsername"><option value="">所有启用账号（全站广播）</option><option v-for="account in accounts" :key="account.username" :value="account.username">{{account.displayName}} · {{account.username}} · {{account.role}}</option></select></label><label>主题<input v-model.trim="form.subject" maxlength="120" required></label><label>正文<textarea v-model.trim="form.body" maxlength="8000" rows="8" required></textarea></label><label>站内链接（可选）<input v-model.trim="form.linkPath" maxlength="500" placeholder="/question-vine?topic=12"></label><p v-if="error" class="form-error">{{error}}</p><p v-if="message" class="form-success">{{message}}</p><button class="primary-button" :disabled="busy">{{busy?'正在投递…':form.targetUsername?'发送给该账号':'向所有人发送'}}</button></section></form></div></template>
